_wantLocalLoop(L,dt,name,on,vol,pitch=1) {
      if (on && L[name]?.playing === false && !L[name]._sfxDeferred && G.audio?.canRearmLoop?.()) { L[name].stop?.(0); L[name] = null; }
      if (on && !L[name]) L[name] = G.audio?.loop?.(name, { volume: 0 });
      const h = L[name];
      if (!h) return;
      h._v = damp(h._v || 0, on ? vol : 0, on ? 10 : 7, dt);
      h.set({ volume: h._v, pitch });
      if (!on && h._v < 0.01) { h.stop(0.05); L[name] = null; }
  }

