_updateLocalLoops(dt) {
    const m = this.match, a = m && !m.attract && !m.paused ? m.local : null;
    if (!(a && a.alive) && !this._loops?.swim && !this._loops?.climb && !this._loops?.enemy_ink_sizzle) return;
    const L = this._loops || (this._loops = {});
    const alive = !!(a && a.alive);
    const swimming = alive && a.anim.form === 'swim';
    if (swimming || L.swim) {
      const hs = alive ? Math.hypot(a.vel.x, a.vel.z) : 0;
      this._wantLocalLoop(L,dt,'swim', swimming && hs > 0.5, Math.min(0.6, hs / 11.8 * 0.6 + 0.08), 0.6 + Math.min(1, hs / 11.8));
    }
    this._wantLocalLoop(L,dt,'climb', alive && a.anim.form === 'climb', 0.5, alive ? 0.6 + Math.min(1, Math.abs(a.vel.y) / 7.5) : 1);
    this._wantLocalLoop(L,dt,'enemy_ink_sizzle', alive && a.grounded && a.groundTeam === 2, 0.45, 1.0);
  }

