_raw(s, receipt) {
    const ws = this.ws;
    if (!ws || ws.readyState !== 1 || ws.bufferedAmount > 512 * 1024) { if (receipt) receipt.reason='unavailable'; return false; }
    if (s.length > 64 * 1024 || utf8ByteLength(s) > 64 * 1024) { if (receipt) receipt.reason='frame-too-large'; return false; }
    this.bytesOut += s.length;
    ws.send(s);
    return true;
  }

