squadTeams(teams, views = null) {
    // The HUD supplies synchronous scratch. Other callers retain the original
    // fresh-array ownership contract.
    if (views) {
      const first = views[0].players, second = views[1].players;
      first.length = 0; second.length = 0;
      let count = 0;
      for (const t of teams || []) for (const p of (t && t.players) || []) {
        if (count < 4) first.push(p); else if (count < 8) second.push(p);
        count++;
      }
      views[0].color = teams && teams[0] && teams[0].color;
      views[1].color = teams && teams[0] && teams[0].color;
      return views;
    }
    const all = [];
    for (const t of teams || []) for (const p of (t && t.players) || []) all.push(p);
    return [{ color: teams && teams[0] && teams[0].color, players: all.slice(0, 4) }, { color: teams && teams[0] && teams[0].color, players: all.slice(4, 8) }];
  }

