_layoutOne(id) {
    if (!this.root) return;
    const safe = this._safe(), prior = this._safeBox, unit = layoutUnit();
    if (!prior || this._layoutWidth !== innerWidth || this._layoutHeight !== innerHeight || this._H !== unit || safe.l !== prior.l || safe.r !== prior.r || safe.t !== prior.t || safe.b !== prior.b) {
      this._layoutAll(); return;
    }
    this._safeBox = safe;
    this._layoutControl(id);
    if (id === 'stick' && !this._stick.active) this._drawStick(false);
    if (this.editing && this._sel) this._layoutCoordinates?.();
  }
